// ---- format.js ----
export const CURRENCY = '₽';

export function formatPrice(value) {
  return value.toFixed(2) + ' ' + CURRENCY;
}

export function formatCount(value, word) {
  return value + ' ' + word;
}

export default function createFormatter() {
  return { formatPrice, formatCount };
}

// ---- main.js ----
import createFormatter, { formatPrice, CURRENCY as CUR } from './format.js';

const title = document.querySelector('#total');
title.textContent = formatPrice(1499.5);   // '1499.50 ₽'
console.log(CUR, createFormatter().formatCount(3, 'товара'));
